from __future__ import annotations

from sterling_models import NodeInventory, OrderLineRequest, Reservation


def _inventory_key(inventory: NodeInventory) -> tuple[str, str]:
    return (inventory.node_id, inventory.item_id)


def _business_key(request: OrderLineRequest) -> tuple[str, str]:
    return (request.order_id, request.line_id)


def _reservation_lookup_key(reservation: Reservation) -> str:
    return reservation.idempotency_key


def _audit(action: str, request: OrderLineRequest, reason: str, reservation_id: str | None = None) -> dict[str, object]:
    return {
        "action": action,
        "order_id": request.order_id,
        "line_id": request.line_id,
        "idempotency_key": request.idempotency_key,
        "reservation_id": reservation_id,
        "reason": reason,
    }


def _result(
    status: str,
    request: OrderLineRequest,
    reservation: Reservation | None,
    inventory: list[NodeInventory],
    audit_events: list[dict[str, object]],
    reason: str,
) -> dict[str, object]:
    return {
        "status": status,
        "order_id": request.order_id,
        "line_id": request.line_id,
        "item_id": request.item_id,
        "selected_node": reservation.node_id if reservation is not None else None,
        "reservation_id": reservation.reservation_id if reservation is not None else None,
        "reserved_quantity": reservation.quantity if reservation is not None else 0,
        "inventory": inventory,
        "audit_events": audit_events,
        "reason": reason,
    }


def _reserve_inventory(inventory: list[NodeInventory], node_id: str, item_id: str, quantity: int) -> list[NodeInventory]:
    updated: list[NodeInventory] = []
    for row in inventory:
        if row.node_id == node_id and row.item_id == item_id:
            updated.append(
                NodeInventory(
                    node_id=row.node_id,
                    item_id=row.item_id,
                    available_quantity=row.available_quantity - quantity,
                    reserved_quantity=row.reserved_quantity + quantity,
                )
            )
        else:
            updated.append(row)
    return updated


def promise_order_line(
    request: OrderLineRequest,
    inventory: list[NodeInventory],
    reservations: list[Reservation],
) -> dict[str, object]:
    existing_by_key = {_reservation_lookup_key(reservation): reservation for reservation in reservations}
    existing = existing_by_key.get(request.idempotency_key)
    if existing is not None:
        return _result(
            "already_reserved",
            request,
            existing,
            inventory,
            [_audit("replay_returned_existing", request, "existing_reservation", existing.reservation_id)],
            "existing_reservation",
        )

    inventory_by_key = {_inventory_key(row): row for row in inventory}
    for node_id in request.preferred_nodes:
        row = inventory_by_key.get((node_id, request.item_id))
        if row is None:
            continue
        if row.available_quantity < request.requested_quantity:
            continue
        reservation = Reservation(
            reservation_id=f"res-{request.order_id}-{request.line_id}-{node_id}",
            order_id=request.order_id,
            line_id=request.line_id,
            item_id=request.item_id,
            node_id=node_id,
            quantity=request.requested_quantity,
            idempotency_key=request.idempotency_key,
        )
        updated_inventory = _reserve_inventory(inventory, node_id, request.item_id, request.requested_quantity)
        return _result(
            "reserved",
            request,
            reservation,
            updated_inventory,
            [_audit("reservation_created", request, "inventory_reserved", reservation.reservation_id)],
            "inventory_reserved",
        )

    return _result(
        "unavailable",
        request,
        None,
        inventory,
        [_audit("reservation_rejected", request, "insufficient_inventory")],
        "insufficient_inventory",
    )


def summarize_promising_run(results: list[dict[str, object]]) -> dict[str, object]:
    return {
        "reserved_count": sum(1 for result in results if result["status"] == "reserved"),
        "replay_count": sum(1 for result in results if result["status"] == "already_reserved"),
        "unavailable_count": sum(1 for result in results if result["status"] == "unavailable"),
        "audit_event_count": sum(len(result["audit_events"]) for result in results),  # type: ignore[arg-type]
        "results": results,
    }


class SterlingOrderPromisingCoordinator:
    def __init__(self, inventory: list[NodeInventory], reservations: list[Reservation] | None = None) -> None:
        self.inventory = list(inventory)
        self.reservations = list(reservations or [])

    def promise(self, request: OrderLineRequest) -> dict[str, object]:
        result = promise_order_line(request, self.inventory, self.reservations)
        self.inventory = list(result["inventory"])  # type: ignore[arg-type]
        if result["status"] == "reserved":
            self.reservations.append(
                Reservation(
                    reservation_id=str(result["reservation_id"]),
                    order_id=request.order_id,
                    line_id=request.line_id,
                    item_id=request.item_id,
                    node_id=str(result["selected_node"]),
                    quantity=int(result["reserved_quantity"]),
                    idempotency_key=request.idempotency_key,
                )
            )
        return result

